import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.loads(sys.stdin.read())

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(name, []).append((pkg['id'], pkg['resolvedVersion']))
    return result

b = extract(baseline)
a = extract(after)
print('Match:', b == a)
